using System.Diagnostics;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using OpenTelemetry;
using OpenTelemetry.Trace;
using OpenTelemetry.Resources;
using OpenTelemetry.Exporter;

namespace MyApp.Evals;

/// <summary>
/// Shared setup for evaluation modes: telemetry, quality, and compare.
/// </summary>
public static class EvalSetup
{
    public static readonly string ReportPath =
        Path.Combine(AppContext.BaseDirectory, "eval-reports");

    /// <summary>
    /// Creates a chat configuration targeting the deployed model for scoring.
    /// </summary>
    public static ChatConfiguration CreateJudgeChatConfig()
    {
        // Uses AZURE_OPENAI_ENDPOINT / AZURE_OPENAI_API_KEY env vars at runtime.
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? "";

        return new ChatConfiguration(
            new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint),
                new System.ClientModel.ApiKeyCredential(key))
                .GetChatClient("gpt-4o-mini").AsIChatClient(),
            "gpt-4o-mini");
    }

    /// <summary>
    /// Standard quality evaluators used in quality and compare modes.
    /// </summary>
    public static IList<IEvaluator> QualityEvaluators() =>
    [
        new CoherenceEvaluator(),
        new RelevanceEvaluator(),
        new FluencyEvaluator(),
        new GroundednessEvaluator(),
    ];

    /// <summary>
    /// Builds an OpenTelemetry TracerProvider that exports to an in-memory list
    /// for telemetry-mode evaluation assertions.
    /// </summary>
    public static TracerProvider CreateTelemetryProvider(List<Activity> exportedActivities)
    {
        return Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("MyApp.Evals"))
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp.Coach")
            .AddInMemoryExporter(exportedActivities)
            .Build()!;
    }
}

using System.Diagnostics;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals.Scenarios;

/// <summary>
/// Telemetry mode: verifies that the agentic app emits correct OpenTelemetry
/// spans/activities for each chat completion call, enabling observability.
/// </summary>
[TestClass]
public class TelemetryEvals
{
    [TestMethod]
    public void TracerProvider_CapturesAIActivities()
    {
        var exportedActivities = new List<Activity>();
        using var provider = EvalSetup.CreateTelemetryProvider(exportedActivities);

        // Simulate an activity from the AI source
        using var source = new ActivitySource("Microsoft.Extensions.AI");
        using var activity = source.StartActivity("chat.completion");
        activity?.SetTag("gen_ai.system", "openai");
        activity?.SetTag("gen_ai.request.model", "gpt-4o-mini");
        activity?.Stop();

        provider.ForceFlush();

        Assert.IsTrue(exportedActivities.Count > 0, "Expected at least one telemetry activity.");
        var captured = exportedActivities[0];
        Assert.AreEqual("chat.completion", captured.OperationName);
        Assert.AreEqual("openai", captured.GetTagItem("gen_ai.system")?.ToString());
    }

    [TestMethod]
    public void TracerProvider_CapturesCoachActivities()
    {
        var exportedActivities = new List<Activity>();
        using var provider = EvalSetup.CreateTelemetryProvider(exportedActivities);

        using var source = new ActivitySource("MyApp.Coach");
        using var activity = source.StartActivity("coach.plan");
        activity?.SetTag("coach.step_count", "3");
        activity?.Stop();

        provider.ForceFlush();

        Assert.IsTrue(exportedActivities.Count > 0, "Expected coach telemetry activity.");
        Assert.AreEqual("coach.plan", exportedActivities[0].OperationName);
    }
}

using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals.Scenarios;

/// <summary>
/// Quality mode: scores agent responses on coherence, relevance, fluency,
/// and groundedness using an LLM-as-judge pipeline.
/// </summary>
[TestClass]
public class QualityEvals
{
    private static readonly ReportingConfiguration s_reportConfig = new(
        new DiskBasedReportingStorage(EvalSetup.ReportPath),
        EvalSetup.QualityEvaluators(),
        chatConfiguration: EvalSetup.CreateJudgeChatConfig());

    [TestMethod]
    public async Task CoachResponse_MeetsQualityThreshold()
    {
        await using var scenario = await s_reportConfig.CreateScenarioRunAsync(
            scenarioName: "CoachBasicAdvice",
            iterationName: "run-1");

        // Simulated turn: user asks for study advice, agent responds.
        var userRequest = "How should I prepare for a math exam?";
        var agentResponse = "Focus on practice problems, review key formulas, "
            + "and take timed mock exams to build confidence and speed.";

        scenario.AddTurn(
            request: userRequest,
            response: agentResponse,
            context: ["Math exam preparation", "Study techniques"]);

        await scenario.EvaluateAsync();

        var coherence = scenario.GetNumericMetricValue(CoherenceEvaluator.CoherenceMetricName);
        var relevance = scenario.GetNumericMetricValue(RelevanceEvaluator.RelevanceMetricName);
        var fluency = scenario.GetNumericMetricValue(FluencyEvaluator.FluencyMetricName);

        // Quality gate: each dimension must score at least 3/5.
        Assert.IsTrue(coherence >= 3, $"Coherence too low: {coherence}");
        Assert.IsTrue(relevance >= 3, $"Relevance too low: {relevance}");
        Assert.IsTrue(fluency >= 3, $"Fluency too low: {fluency}");
    }

    [TestMethod]
    public async Task CoachResponse_Groundedness()
    {
        await using var scenario = await s_reportConfig.CreateScenarioRunAsync(
            scenarioName: "CoachGroundedness",
            iterationName: "run-1");

        var userRequest = "What are the benefits of spaced repetition?";
        var agentResponse = "Spaced repetition improves long-term retention by "
            + "scheduling reviews at increasing intervals, leveraging the spacing effect.";

        scenario.AddTurn(
            request: userRequest,
            response: agentResponse,
            context: [
                "Spaced repetition is a learning technique that schedules reviews at increasing intervals.",
                "The spacing effect shows that information is better retained with spaced practice."
            ]);

        await scenario.EvaluateAsync();

        var groundedness = scenario.GetNumericMetricValue(
            GroundednessEvaluator.GroundednessMetricName);
        Assert.IsTrue(groundedness >= 3, $"Groundedness too low: {groundedness}");
    }
}

using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals.Scenarios;

/// <summary>
/// Compare mode: runs the same scenario against two model configurations and
/// reports quality metrics side-by-side, enabling regression detection.
/// </summary>
[TestClass]
public class CompareEvals
{
    private static readonly string s_reportPath =
        Path.Combine(EvalSetup.ReportPath, "compare");

    [TestMethod]
    public async Task CompareBaseline_Vs_Candidate()
    {
        var evaluators = EvalSetup.QualityEvaluators();
        var chatConfig = EvalSetup.CreateJudgeChatConfig();

        var reportConfig = new ReportingConfiguration(
            new DiskBasedReportingStorage(s_reportPath),
            evaluators,
            chatConfiguration: chatConfig);

        // --- Baseline run ---
        await using var baselineRun = await reportConfig.CreateScenarioRunAsync(
            scenarioName: "CoachAdvice_Compare",
            iterationName: "baseline");

        baselineRun.AddTurn(
            request: "How do I stay focused while studying?",
            response: "Try the Pomodoro technique: study for 25 minutes, then take a 5-minute break.",
            context: ["Focus techniques", "Pomodoro method"]);

        await baselineRun.EvaluateAsync();

        // --- Candidate run ---
        await using var candidateRun = await reportConfig.CreateScenarioRunAsync(
            scenarioName: "CoachAdvice_Compare",
            iterationName: "candidate");

        candidateRun.AddTurn(
            request: "How do I stay focused while studying?",
            response: "Use time-boxed study sessions of 25 minutes with short breaks. "
                + "Eliminate distractions by silencing notifications and using a dedicated workspace.",
            context: ["Focus techniques", "Pomodoro method", "Distraction management"]);

        await candidateRun.EvaluateAsync();

        // Extract scores for comparison
        var baselineCoherence = baselineRun.GetNumericMetricValue(
            CoherenceEvaluator.CoherenceMetricName);
        var candidateCoherence = candidateRun.GetNumericMetricValue(
            CoherenceEvaluator.CoherenceMetricName);

        var baselineRelevance = baselineRun.GetNumericMetricValue(
            RelevanceEvaluator.RelevanceMetricName);
        var candidateRelevance = candidateRun.GetNumericMetricValue(
            RelevanceEvaluator.RelevanceMetricName);

        // Compare: candidate should not regress more than 1 point on any dimension.
        Assert.IsTrue(
            candidateCoherence >= baselineCoherence - 1,
            $"Candidate coherence regressed: {candidateCoherence} vs baseline {baselineCoherence}");
        Assert.IsTrue(
            candidateRelevance >= baselineRelevance - 1,
            $"Candidate relevance regressed: {candidateRelevance} vs baseline {baselineRelevance}");
    }
}

