using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals.Scenarios;

/// <summary>
/// Compare mode: runs the same scenario against two model configurations and
/// reports quality metrics side-by-side, enabling regression detection.
/// </summary>
[TestClass]
public class CompareEvals
{
    private static readonly string s_reportPath =
        Path.Combine(EvalSetup.ReportPath, "compare");

    [TestMethod]
    public async Task CompareBaseline_Vs_Candidate()
    {
        var evaluators = EvalSetup.QualityEvaluators();
        var chatConfig = EvalSetup.CreateJudgeChatConfig();

        var reportConfig = new ReportingConfiguration(
            new DiskBasedReportingStorage(s_reportPath),
            evaluators,
            chatConfiguration: chatConfig);

        // --- Baseline run ---
        await using var baselineRun = await reportConfig.CreateScenarioRunAsync(
            scenarioName: "CoachAdvice_Compare",
            iterationName: "baseline");

        baselineRun.AddTurn(
            request: "How do I stay focused while studying?",
            response: "Try the Pomodoro technique: study for 25 minutes, then take a 5-minute break.",
            context: ["Focus techniques", "Pomodoro method"]);

        await baselineRun.EvaluateAsync();

        // --- Candidate run ---
        await using var candidateRun = await reportConfig.CreateScenarioRunAsync(
            scenarioName: "CoachAdvice_Compare",
            iterationName: "candidate");

        candidateRun.AddTurn(
            request: "How do I stay focused while studying?",
            response: "Use time-boxed study sessions of 25 minutes with short breaks. "
                + "Eliminate distractions by silencing notifications and using a dedicated workspace.",
            context: ["Focus techniques", "Pomodoro method", "Distraction management"]);

        await candidateRun.EvaluateAsync();

        // Extract scores for comparison
        var baselineCoherence = baselineRun.GetNumericMetricValue(
            CoherenceEvaluator.CoherenceMetricName);
        var candidateCoherence = candidateRun.GetNumericMetricValue(
            CoherenceEvaluator.CoherenceMetricName);

        var baselineRelevance = baselineRun.GetNumericMetricValue(
            RelevanceEvaluator.RelevanceMetricName);
        var candidateRelevance = candidateRun.GetNumericMetricValue(
            RelevanceEvaluator.RelevanceMetricName);

        // Compare: candidate should not regress more than 1 point on any dimension.
        Assert.IsTrue(
            candidateCoherence >= baselineCoherence - 1,
            $"Candidate coherence regressed: {candidateCoherence} vs baseline {baselineCoherence}");
        Assert.IsTrue(
            candidateRelevance >= baselineRelevance - 1,
            $"Candidate relevance regressed: {candidateRelevance} vs baseline {baselineRelevance}");
    }
}

